INSERT OR IGNORE INTO products (id, slug, category_id, brand_id, title, description, long_description, specs_json, whats_included_json, image_url, gallery_json, rating_avg, rating_count, sales_count, is_flash_deal) VALUES

  (1, 'tecno-camon-30-pro-5g-256gb-dark-silver', 2, 20, 'Tecno Camon 30 Pro 5G 256GB Dark Silver', '256GB/8GB, 108MP camera, 5000mAh battery, 5G-ready.', 'The Tecno Camon 30 Pro 5G delivers flagship-grade photography with a 108MP main sensor and OIS, wrapped in a slim glass-back design. All-day 5000mAh battery with 45W fast charging gets you through even the busiest Lagos commute. Runs HiOS 14 on Android 14.', '{"Screen": "6.78\" AMOLED, 120Hz", "RAM": "8GB", "Storage": "256GB", "Camera": "108MP + 2MP + AI Lens", "Battery": "5000mAh, 45W charging", "Network": "5G Dual SIM", "OS": "Android 14 / HiOS 14"}', '["1x Tecno Camon 30 Pro 5G", "1x 45W Charger", "1x USB-C Cable", "1x Clear Case", "1x SIM Eject Tool"]', '/static/products/product-1.jpg', '["/static/products/product-1.jpg"]', 4.6, 312, 890, 1),
  (2, 'infinix-note-40-pro-5g-256gb-vintage-green', 2, 21, 'Infinix Note 40 Pro 5G 256GB Vintage Green', '256GB/8GB, 108MP OIS, 5000mAh, 45W fast charge.', 'Infinix Note 40 Pro 5G brings a curved AMOLED display and a genuinely capable 108MP OIS camera to the mid-range segment. Built for power users who stream, game and shoot content daily.', '{"Screen": "6.78\" Curved AMOLED, 120Hz", "RAM": "8GB (+8GB extended)", "Storage": "256GB", "Camera": "108MP OIS + 2MP", "Battery": "5000mAh, 45W", "Network": "5G Dual SIM"}', '["1x Infinix Note 40 Pro 5G", "1x 45W Charger", "1x USB-C Cable", "1x Protective Case"]', '/static/products/product-2.jpg', '["/static/products/product-2.jpg"]', 4.5, 201, 560, 0),
  (3, 'samsung-galaxy-a55-5g-256gb-awesome-navy', 2, 2, 'Samsung Galaxy A55 5G 256GB Awesome Navy', '8GB RAM, 256GB storage, 50MP OIS triple camera, IP67.', 'The Galaxy A55 5G brings Samsung flagship durability (IP67 water resistance, Gorilla Glass Victus+) to the mid-range with a vivid Super AMOLED display and reliable 50MP OIS main camera. Backed by 4 years of OS updates.', '{"Screen": "6.6\" Super AMOLED, 120Hz", "RAM": "8GB", "Storage": "256GB", "Camera": "50MP OIS + 12MP UW + 5MP Macro", "Battery": "5000mAh, 25W", "Water resistance": "IP67"}', '["1x Galaxy A55 5G", "1x USB-C Cable", "1x SIM Eject Tool (charger sold separately per EU policy)"]', '/static/products/product-3.jpg', '["/static/products/product-3.jpg"]', 4.7, 489, 1120, 0),
  (4, 'apple-iphone-15-128gb-blue', 2, 1, 'Apple iPhone 15 128GB Blue', 'A16 Bionic, 48MP main camera, Dynamic Island, USB-C.', 'iPhone 15 brings Dynamic Island, a 48MP main camera with 2x optical-quality zoom, and USB-C to the standard lineup. Powered by the A16 Bionic chip for smooth all-day performance. Nigerian units come with a 1-year Apple warranty via authorized resellers.', '{"Screen": "6.1\" Super Retina XDR OLED", "Chip": "A16 Bionic", "Storage": "128GB", "Camera": "48MP Main + 12MP Ultra Wide", "Battery": "Up to 20 hrs video", "Port": "USB-C"}', '["1x iPhone 15", "1x USB-C to USB-C Cable", "1x Apple sticker (charger sold separately)"]', '/static/products/product-4.jpg', '["/static/products/product-4.jpg"]', 4.9, 743, 2340, 0),
  (5, 'samsung-galaxy-tab-a9-64gb-wifi-graphite', 2, 2, 'Samsung Galaxy Tab A9+ 64GB WiFi Graphite', '11" display, 7040mAh battery, quad speakers.', 'A spacious 11-inch tablet ideal for streaming, e-learning and light productivity. Quad speakers tuned by AKG make it a great NaijaStream companion.', '{"Screen": "11.0\" TFT, 90Hz", "RAM": "4GB", "Storage": "64GB (expandable)", "Battery": "7040mAh", "Speakers": "Quad, Dolby Atmos"}', '["1x Galaxy Tab A9+", "1x USB-C Cable", "1x 33W Charger"]', '/static/products/product-5.jpg', '["/static/products/product-5.jpg"]', 4.4, 156, 290, 0),
  (6, 'apple-macbook-air-m3-13-8gb-256gb-midnight', 3, 1, 'Apple MacBook Air M3 13" 8GB/256GB Midnight', 'Apple M3 chip, all-day battery, Liquid Retina display.', 'The MacBook Air with M3 chip delivers exceptional performance-per-watt for creative and professional work, with a fanless design that stays silent under everyday load. Up to 18 hours of battery life on a single charge.', '{"Chip": "Apple M3 (8-core CPU / 8-core GPU)", "RAM": "8GB unified memory", "Storage": "256GB SSD", "Display": "13.6\" Liquid Retina", "Battery": "Up to 18 hours"}', '["1x MacBook Air M3", "1x 30W USB-C Power Adapter", "1x USB-C Charge Cable"]', '/static/products/product-6.jpg', '["/static/products/product-6.jpg"]', 4.9, 298, 540, 0),
  (7, 'hp-pavilion-15-core-i7-12th-gen-16gb-512gb', 3, 5, 'HP Pavilion 15 Core i7 12th Gen 16GB/512GB', 'Intel Core i7-1255U, 16GB RAM, 512GB SSD, FHD display.', 'A capable everyday laptop for work, study and entertainment, with enough RAM and SSD headroom for multitasking across office apps, browsers and light editing work.', '{"Processor": "Intel Core i7-1255U (12th Gen)", "RAM": "16GB DDR4", "Storage": "512GB SSD", "Display": "15.6\" FHD IPS", "Graphics": "Intel Iris Xe"}', '["1x HP Pavilion 15", "1x 65W Charger", "1x User Guide"]', '/static/products/product-7.jpg', '["/static/products/product-7.jpg"]', 4.4, 167, 410, 0),
  (8, 'samsung-galaxy-book4-core-i5-13th-gen-8gb-512gb', 3, 2, 'Samsung Galaxy Book4 Core i5 13th Gen 8GB/512GB', 'Intel Core i5-1335U, 8GB RAM, lightweight 1.55kg chassis.', 'A slim, lightweight laptop built for portability without sacrificing performance — great for students and professionals who move between meetings and campuses across Lagos and Abuja.', '{"Processor": "Intel Core i5-1335U (13th Gen)", "RAM": "8GB LPDDR5", "Storage": "512GB SSD", "Display": "15.6\" FHD", "Weight": "1.55kg"}', '["1x Galaxy Book4", "1x 65W Charger"]', '/static/products/product-8.jpg', '["/static/products/product-8.jpg"]', 4.5, 89, 180, 0),
  (9, 'lg-55-oled-evo-c3-4k-smart-tv', 4, 6, 'LG 55" OLED evo C3 4K Smart TV', 'Self-lit pixels, Dolby Vision & Atmos, webOS 23.', 'Perfect blacks and vivid highlights from self-lit OLED pixels, tuned for both blockbuster movie nights and console gaming with 4K/120Hz support. webOS 23 brings NaijaStream and other apps to your living room.', '{"Screen size": "55 inch", "Resolution": "4K UHD (3840x2160)", "Panel": "OLED evo", "HDR": "Dolby Vision, HDR10, HLG", "Smart platform": "webOS 23", "Refresh rate": "120Hz"}', '["1x LG 55\" OLED TV", "1x Magic Remote", "1x Stand", "1x Power Cable"]', '/static/products/product-9.jpg', '["/static/products/product-9.jpg"]', 4.7, 312, 210, 0),
  (10, 'hisense-43-a4h-full-hd-smart-tv', 4, 19, 'Hisense 43" A4H Full HD Smart TV', '43-inch, VIDAA Smart OS, dual-band WiFi, built-in Bluetooth.', 'An affordable, reliable smart TV for the living room or bedroom, with VIDAA smart apps and Bluetooth audio pairing baked in.', '{"Screen size": "43 inch", "Resolution": "Full HD (1920x1080)", "Smart platform": "VIDAA", "Connectivity": "WiFi, Bluetooth, 2x HDMI"}', '["1x Hisense 43\" TV", "1x Remote", "1x Stand"]', '/static/products/product-10.jpg', '["/static/products/product-10.jpg"]', 4.3, 178, 340, 1),
  (11, 'jbl-charge-5-bluetooth-speaker-teal', 4, 4, 'JBL Charge 5 Bluetooth Speaker Teal', 'Waterproof, powerbank function, 20-hour playtime.', 'Take your playlist anywhere — JBL Charge 5 is IP67 waterproof and dustproof, delivers deep JBL Pro Sound bass, and doubles as a powerbank for your phone via USB-C output.', '{"Battery life": "Up to 20 hours", "Waterproofing": "IP67", "Output": "40W RMS", "Connectivity": "Bluetooth 5.1"}', '["1x JBL Charge 5", "1x USB-C Charging Cable", "1x Quick Start Guide"]', '/static/products/product-11.jpg', '["/static/products/product-11.jpg"]', 4.5, 267, 780, 1),
  (12, 'sony-wh-1000xm5-noise-cancelling-headphones', 4, 3, 'Sony WH-1000XM5 Noise Cancelling Headphones', 'Industry-leading ANC, 30-hour battery, crystal-clear calls.', 'Two processors control eight microphones for unprecedented noise cancellation. Multi-point connection lets you switch seamlessly between devices, and 30-hour battery life covers even the longest travel days.', '{"Battery life": "Up to 30 hours (ANC on)", "Noise cancellation": "Dual Processor QN1 + V1", "Driver": "30mm", "Weight": "250g"}', '["1x WH-1000XM5", "1x Carrying Case", "1x USB-C Cable", "1x Audio Cable"]', '/static/products/product-12.jpg', '["/static/products/product-12.jpg"]', 4.7, 134, 320, 0),
  (13, 'slim-power-bank-10000mah-fast-charging', 5, 1, 'Slim Power Bank 10000mAh Fast Charging', 'Ultra-slim dual-output power bank, 22.5W fast charge.', 'A pocket-friendly power bank that keeps your phone alive through long Lagos traffic days, with dual USB output so you can charge two devices simultaneously.', '{"Capacity": "10000mAh", "Output": "22.5W Max, Dual USB-A + USB-C", "Charging time": "~2.5 hours"}', '["1x Power Bank", "1x USB-C Charging Cable"]', '/static/products/product-13.jpg', '["/static/products/product-13.jpg"]', 4.1, 244, 1450, 1),
  (14, 'anker-20000mah-solar-power-bank', 5, 23, 'Anker 20000mAh Solar Power Bank', 'High-capacity solar-assisted power bank for outdoor use and outages.', 'Built for Nigeria''s power realities — a high-capacity bank with a solar panel assist for topping up during outages, plus a built-in flashlight for emergencies.', '{"Capacity": "20000mAh", "Output": "18W fast charge", "Extra": "Built-in LED flashlight, solar panel"}', '["1x Solar Power Bank", "1x USB-C Cable"]', '/static/products/product-14.jpg', '["/static/products/product-14.jpg"]', 4.3, 267, 690, 1),
  (15, 'nike-air-force-1-low-white-original', 13, 11, 'Nike Air Force 1 Low White Original', 'Classic white sneakers, timeless style, all-day comfort.', 'The AF1 needs no introduction — full-grain leather upper, Nike Air cushioning, and a silhouette that has anchored sneaker culture since 1982.', '{"Material": "Full-grain leather", "Sole": "Rubber with Nike Air cushioning", "Closure": "Lace-up"}', '["1x Pair Nike Air Force 1", "1x Shoe Box", "1x Dust Bag"]', '/static/products/product-15.jpg', '["/static/products/product-15.jpg"]', 4.6, 445, 1230, 0),
  (16, 'nike-mercurial-vapor-16-elite-fg-football-boots', 13, 11, 'Nike Mercurial Vapor 16 Elite FG Football Boots', 'Elite firm-ground boots built for speed and agility.', 'Engineered for explosive acceleration on firm pitches — a featherweight Vaporposite+ plate and Speed Tapered Fit designed with elite pace players in mind.', '{"Ground type": "Firm Ground (FG)", "Upper": "Vaporposite+", "Fit": "Speed Tapered"}', '["1x Pair Football Boots", "1x Boot Bag"]', '/static/products/product-16.jpg', '["/static/products/product-16.jpg"]', 4.5, 189, 410, 0),
  (17, 'handmade-leather-tote-bag', 14, NULL, 'Handmade Leather Tote Bag', 'Genuine leather tote, hand-stitched by Lagos artisans.', 'Every tote is hand-cut and stitched by leatherworkers in Surulere, Lagos, using full-grain cowhide that develops a richer patina with age.', '{"Material": "Full-grain leather", "Dimensions": "38cm x 30cm x 12cm", "Origin": "Handmade in Lagos, Nigeria"}', '["1x Leather Tote Bag", "1x Care Card"]', '/static/products/product-17.jpg', '["/static/products/product-17.jpg"]', 4.5, 178, 290, 0),
  (18, 'adire-hand-dyed-kaftan-women-premium', 11, NULL, 'Adire Hand-Dyed Kaftan Women Premium', 'Traditional Adire fabric kaftan, hand-dyed, premium finish.', 'Woven from the deep indigo tie-dye tradition of the Yoruba, each Adire kaftan is uniquely patterned — no two pieces are exactly alike.', '{"Fabric": "100% Cotton Adire", "Origin": "Abeokuta, Nigeria", "Care": "Hand wash cold, line dry"}', '["1x Adire Kaftan"]', '/static/products/product-18.jpg', '["/static/products/product-18.jpg"]', 4.6, 203, 340, 0),
  (19, 'premium-aso-oke-ankara-senator-suit-men', 11, NULL, 'Premium Aso-Oke Ankara Senator Suit Men', 'Sharp senator suit with Aso-Oke trim, made in Nigeria.', 'A tailored senator silhouette finished with hand-woven Aso-Oke trim at the collar and cuffs — built for weddings, owambe and formal occasions.', '{"Fabric": "Cotton blend with Aso-Oke trim", "Fit": "Tailored senator cut", "Origin": "Made in Nigeria"}', '["1x Senator Top", "1x Trouser", "1x Cap"]', '/static/products/product-19.jpg', '["/static/products/product-19.jpg"]', 4.5, 312, 520, 0),
  (20, 'binatone-4-burner-gas-cooker-with-oven', 21, 10, 'Binatone 4-Burner Gas Cooker with Oven', 'Durable 4-burner gas cooker, built-in oven and grill.', 'A kitchen workhorse built for Nigerian households — 4 open burners for quick stovetop cooking plus a full-size oven and grill for baking and roasting.', '{"Burners": "4 (mixed sizes)", "Oven capacity": "60L", "Ignition": "Auto ignition", "Material": "Enamel-coated steel"}', '["1x Gas Cooker", "1x Grill Tray", "1x User Manual"]', '/static/products/product-20.jpg', '["/static/products/product-20.jpg"]', 4.3, 312, 540, 0),
  (21, 'blender-juicer-combo-set-2-in-1', 21, NULL, 'Blender & Juicer Combo Set 2-in-1', '2-in-1 kitchen appliance for smoothies, juices and food prep.', 'Handles everything from pepper-blending for stew base to morning smoothies, with a 1.5L jar and a separate juicer attachment.', '{"Jar capacity": "1.5L", "Power": "450W", "Speed settings": "3 + pulse"}', '["1x Blender Base", "1x Blending Jar", "1x Juicer Attachment"]', '/static/products/product-21.jpg', '["/static/products/product-21.jpg"]', 4.2, 158, 410, 1),
  (22, 'scanfrost-200l-chest-freezer', 22, 9, 'Scanfrost 200L Chest Freezer', 'Energy-efficient chest freezer, fast-freeze function.', 'A reliable chest freezer built for Nigerian voltage fluctuations, with a fast-freeze switch to protect food during power restoration after outages.', '{"Capacity": "200 Litres", "Energy rating": "A+", "Extra": "Fast-freeze function, lock & key"}', '["1x Chest Freezer", "1x Basket", "1x Key Set"]', '/static/products/product-22.jpg', '["/static/products/product-22.jpg"]', 4.4, 245, 290, 0),
  (23, 'midea-1-5hp-split-inverter-ac-r32', 22, 8, 'Midea 1.5HP Split Inverter AC R32', 'Energy-saving inverter AC, quiet operation, fast cooling.', 'Inverter compressor technology cuts energy use versus fixed-speed ACs while cooling faster and running quieter — ideal for Lagos and Port Harcourt heat.', '{"Capacity": "1.5HP", "Compressor": "Inverter", "Refrigerant": "R32 (eco-friendly)", "Noise level": "Low (indoor <26dB)"}', '["1x Indoor Unit", "1x Outdoor Unit", "1x Remote", "1x Installation Kit"]', '/static/products/product-23.jpg', '["/static/products/product-23.jpg"]', 4.5, 378, 410, 0),
  (24, 'dyson-v15-detect-cordless-vacuum', 23, 7, 'Dyson V15 Detect Cordless Vacuum', 'Laser dust detection, powerful suction, up to 60 min runtime.', 'A laser reveals microscopic dust invisible to the naked eye, while the piezo sensor counts and sizes particles in real time on the LCD screen.', '{"Runtime": "Up to 60 minutes", "Bin capacity": "0.77L", "Filtration": "Whole-machine HEPA"}', '["1x Dyson V15", "1x Laser Head", "1x Combination Tool", "1x Charging Dock"]', '/static/products/product-24.jpg', '["/static/products/product-24.jpg"]', 4.6, 92, 110, 0),
  (25, '4-piece-duvet-pillowcase-set', 24, NULL, '4-Piece Duvet & Pillowcase Set', 'Soft cotton-blend duvet set, machine washable, fade resistant.', 'A hotel-quality duvet set that holds its color through repeated washes — comes with a duvet cover, fitted sheet and two pillowcases.', '{"Material": "Cotton-polyester blend", "Set includes": "Duvet cover, fitted sheet, 2 pillowcases", "Size": "Queen"}', '["1x Duvet Cover", "1x Fitted Sheet", "2x Pillowcases"]', '/static/products/product-25.jpg', '["/static/products/product-25.jpg"]', 4.6, 71, 190, 1),
  (26, 'indomie-super-pack-chicken-flavour-40-pack', 31, 14, 'Indomie Super Pack Chicken Flavour 40-Pack', 'Nigeria''s favourite instant noodles, chicken flavour, 40 sachets.', 'A pantry staple in every Nigerian home — 40 sachets of the chicken flavour that started it all, great for bulk buying for the family or a small shop.', '{"Flavour": "Chicken", "Pack size": "40 sachets x 70g", "Shelf life": "12 months"}', '["40x Indomie Noodles Sachets"]', '/static/products/product-26.jpg', '["/static/products/product-26.jpg"]', 4.8, 1200, 5400, 1),
  (27, 'golden-penny-semolina-5kg', 31, 16, 'Golden Penny Semolina 5kg', 'Premium quality semolina for smooth, lump-free swallow.', 'Milled for a smooth, lump-free swallow every time — a kitchen essential across Nigerian households for eba and semo.', '{"Weight": "5kg", "Type": "Semolina", "Shelf life": "12 months"}', '["1x 5kg Semolina Bag"]', '/static/products/product-27.jpg', '["/static/products/product-27.jpg"]', 4.6, 678, 2100, 0),
  (28, 'milo-chocolate-malt-drink-1kg-tin', 32, 15, 'Milo Chocolate Malt Drink 1kg Tin', 'Energy-giving chocolate malt drink for the whole family.', 'A breakfast staple fortified with vitamins and minerals — the tin every Nigerian kitchen has had at some point.', '{"Weight": "1kg", "Type": "Chocolate malt drink"}', '["1x 1kg Milo Tin"]', '/static/products/product-28.jpg', '["/static/products/product-28.jpg"]', 4.7, 892, 3200, 1),
  (29, 'peak-milk-powder-full-cream-900g', 32, 28, 'Peak Milk Powder Full Cream 900g', 'Full cream powdered milk, rich and creamy taste.', 'Trusted by Nigerian households for decades — rich, creamy full cream milk powder for tea, cereal and cooking.', '{"Weight": "900g", "Type": "Full cream powdered milk"}', '["1x 900g Peak Milk Tin"]', '/static/products/product-29.jpg', '["/static/products/product-29.jpg"]', 4.7, 540, 1890, 0),
  (30, 'ariel-automatic-washing-powder-3kg', 33, 26, 'Ariel Automatic Washing Powder 3kg', 'Powerful stain removal, fresh scent, for automatic machines.', 'Formulated for automatic washing machines with deep stain-removing power and a long-lasting fresh scent.', '{"Weight": "3kg", "Type": "Automatic washing powder"}', '["1x 3kg Ariel Pack"]', '/static/products/product-30.jpg', '["/static/products/product-30.jpg"]', 4.5, 312, 980, 0),
  (31, 'dettol-antiseptic-liquid-500ml', 33, 27, 'Dettol Antiseptic Liquid 500ml', 'Trusted antiseptic disinfectant for home and personal hygiene.', 'A household name for hygiene across Nigeria — use for wound cleaning, surface disinfecting, and laundry hygiene.', '{"Volume": "500ml", "Type": "Antiseptic disinfectant"}', '["1x 500ml Dettol Bottle"]', '/static/products/product-31.jpg', '["/static/products/product-31.jpg"]', 4.7, 456, 1560, 0),
  (32, 'jamaican-black-castor-oil-4oz-original', 41, NULL, 'Jamaican Black Castor Oil 4oz Original', 'Pure black castor oil for hair growth and scalp health.', 'Cold-pressed and unrefined, this Jamaican black castor oil is a staple in Nigerian natural hair routines for scalp health and growth.', '{"Volume": "4oz (118ml)", "Type": "Cold-pressed castor oil"}', '["1x 4oz Castor Oil Bottle"]', '/static/products/product-32.jpg', '["/static/products/product-32.jpg"]', 4.5, 823, 2340, 1),
  (33, 'olay-total-effects-7-in-1-day-cream-spf15', 41, 24, 'Olay Total Effects 7-in-1 Day Cream SPF15', 'Anti-aging day cream with 7 skin benefits and sun protection.', 'Targets seven signs of aging in one step — fine lines, uneven tone, dullness and more — with SPF15 protection for daytime wear under the Nigerian sun.', '{"Volume": "50g", "SPF": "15", "Skin concerns": "Anti-aging, brightening, hydration"}', '["1x 50g Day Cream Jar"]', '/static/products/product-33.jpg', '["/static/products/product-33.jpg"]', 4.5, 534, 1230, 0),
  (34, 'zaron-matte-foundation-full-coverage', 43, 13, 'Zaron Matte Foundation Full Coverage', 'Full coverage matte foundation, made for Nigerian skin tones.', 'Formulated with a wider shade range for melanin-rich skin tones, this matte foundation resists Lagos humidity for a full-day finish.', '{"Volume": "30ml", "Finish": "Matte", "Coverage": "Full"}', '["1x 30ml Foundation Bottle"]', '/static/products/product-34.jpg', '["/static/products/product-34.jpg"]', 4.4, 289, 760, 0),
  (35, 'decathlon-rubber-dumbbell-pair-10kg', 50, NULL, 'Decathlon Rubber Dumbbell Pair 10kg', 'Rubber-coated dumbbells for home strength training.', 'A pair of rubber-coated cast iron dumbbells that protect your floors and reduce noise, ideal for a Lagos apartment home gym.', '{"Weight per dumbbell": "10kg (pair = 20kg total)", "Coating": "Rubber-coated cast iron"}', '["2x 10kg Dumbbells"]', '/static/products/product-35.jpg', '["/static/products/product-35.jpg"]', 4.4, 312, 540, 0),
  (36, 'yoga-mat-premium-non-slip-6mm', 50, NULL, 'Yoga Mat Premium Non-Slip 6mm', 'Extra-thick non-slip yoga and exercise mat with carry strap.', 'A 6mm-thick non-slip mat that cushions joints for yoga, home workouts and stretching routines, with a carry strap for the gym.', '{"Thickness": "6mm", "Material": "NBR foam", "Includes": "Carry strap"}', '["1x Yoga Mat", "1x Carry Strap"]', '/static/products/product-36.jpg', '["/static/products/product-36.jpg"]', 4.3, 198, 620, 1),
  (37, 'baby-dry-pants-size-4-pack-of-44', 60, NULL, 'Baby Dry Pants Size 4 Pack of 44', 'All-night dryness, comfortable fit, breathable material.', 'Breathable, all-night dryness for active toddlers — Size 4 fits 9-14kg with a wetness indicator strip for easy checking.', '{"Size": "4 (9-14kg)", "Pack size": "44 pieces", "Feature": "Wetness indicator"}', '["44x Diaper Pants"]', '/static/products/product-37.jpg', '["/static/products/product-37.jpg"]', 4.6, 421, 1560, 0),
  (38, 'baby-formula-milk-stage-1-900g', 60, NULL, 'Baby Formula Milk Stage 1 900g', 'Infant formula for 0-6 months, iron-fortified.', 'A complete nutrition formula for infants from birth to 6 months, fortified with iron and essential vitamins for healthy development.', '{"Stage": "1 (0-6 months)", "Weight": "900g", "Fortified": "Iron, Vitamin D, DHA"}', '["1x 900g Formula Tin"]', '/static/products/product-38.jpg', '["/static/products/product-38.jpg"]', 4.7, 289, 780, 0),
  (39, 'jameson-irish-whiskey-75cl', 70, NULL, 'Jameson Irish Whiskey 75cl', 'Triple-distilled Irish whiskey, smooth finish.', 'Triple-distilled for exceptional smoothness — a globally recognized Irish whiskey, sold here through licensed 18+ verified delivery only.', '{"Volume": "75cl", "ABV": "40%", "Age verification": "Required at delivery (18+)"}', '["1x 75cl Bottle"]', '/static/products/product-39.jpg', '["/static/products/product-39.jpg"]', 4.7, 210, 480, 0),
  (40, 'orijin-bitters-20cl', 70, 18, 'Orijin Bitters 20cl', 'Nigerian herbal bitters blend with natural botanicals.', 'A homegrown Nigerian bitters brand blending botanicals for a distinctive taste, popular at gatherings across the country.', '{"Volume": "20cl", "ABV": "25%"}', '["1x 20cl Bottle"]', '/static/products/product-40.jpg', '["/static/products/product-40.jpg"]', 4.6, 178, 620, 0),
  (41, 'rich-dad-poor-dad-robert-kiyosaki', 80, NULL, 'Rich Dad Poor Dad - Robert Kiyosaki', 'The #1 personal finance book, timeless money lessons.', 'A perennial bestseller that reshaped how a generation thinks about assets, liabilities and financial education.', '{"Format": "Paperback", "Pages": "336", "Language": "English"}', '["1x Paperback Book"]', '/static/products/product-41.jpg', '["/static/products/product-41.jpg"]', 4.8, 1500, 4200, 0),
  (42, 'the-spider-king-s-daughter-chibundu-onuzo', 80, NULL, 'The Spider King''s Daughter - Chibundu Onuzo', 'An acclaimed Nigerian coming-of-age love story set in Lagos.', 'A celebrated debut novel exploring class and love across Lagos''s social divide, from a rising star of Nigerian literature.', '{"Format": "Paperback", "Pages": "320", "Language": "English"}', '["1x Paperback Book"]', '/static/products/product-42.jpg', '["/static/products/product-42.jpg"]', 4.5, 234, 610, 0),
  (43, 'michelin-primacy-4-tyre-195-65-r15', 90, NULL, 'Michelin Primacy 4 Tyre 195/65 R15', 'Durable, fuel-efficient tyre with excellent wet grip.', 'Engineered for consistent braking performance even as the tyre wears, with excellent wet-weather grip for Nigeria''s rainy season.', '{"Size": "195/65 R15", "Type": "Passenger car tyre"}', '["1x Tyre"]', '/static/products/product-43.jpg', '["/static/products/product-43.jpg"]', 4.5, 234, 410, 0),
  (44, 'duralast-gold-60ah-car-battery-din60', 90, NULL, 'Duralast Gold 60Ah Car Battery DIN60', 'Maintenance-free car battery with 2-year warranty.', 'A maintenance-free battery with reliable cold-cranking performance, backed by a 2-year replacement warranty.', '{"Capacity": "60Ah", "Type": "DIN60, maintenance-free"}', '["1x Car Battery"]', '/static/products/product-44.jpg', '["/static/products/product-44.jpg"]', 4.4, 156, 290, 0);

